"""Conveyor S1 V1.0 skill catalogue."""
SKILLS = {}

def skill(key, name, group, deal, keep, text):
    SKILLS[key] = dict(id=key, name=name, group=group, deal=deal, keep=keep, text=text)

skill('balance', '转换', 0, 7, 7, '出牌阶段前，可选择是否发动技能。\n\n发动技能后，选几张手牌，点击“发动转换”：弃掉这些牌（如果单次弃置所有牌不视为出完牌），然后再获得同样数量的牌。这些转换后的牌可以再次进行选择，然后再次发动转换。\n\n发动技能后跳过出牌阶段和抽牌阶段。')
skill('anchor', '稳阵', 0, 8, 6, '急牌轮换时，你保留自己的手牌，不参与交换。\n\n急牌让你抓两张时只抓一张。\n\n你的技能不会被禁用。你不会被禁手。')
skill('leap', '跨级', 0, 10, 8, '你的 3 至 A 提高三级，你的王牌永远是最大的单牌，大于其他玩家的大王。主牌不变。2提升至主牌大小。\n\n加点时不跳过主牌原来的位置，经过 A 后最高到主牌。例如主牌是 7 时，5 变 8，J 变 A，K 和 A 变主牌。手牌会同时显示原点数和实际点数。')
skill('stars', '守望', 0, 9, 6, '出牌阶段前，你可以调整牌堆顶部的顺序。展示张数等于仍在场的玩家手牌数。\n\n按想要的顺序依次点击所有展示牌，再确认；先点的牌放在最上面。牌堆不够时，有几张就排几张。')
skill('reflux', '回收·新世代', 0, 8, 7, '一次出三张或更多时，禁用除你以外所有玩家技能一回合。')
skill('clean', '净化', 0, 8, 4, '拿到 3、4、5、6、7 时，把它们弃入弃牌堆并补牌，直到拿到能留下的牌。开局发牌也一样，在选牌期间也不会拿到这五张牌。\n\n如果其中有本局主牌，主牌不可弃置，其余换掉。')
skill('money', '聚宝', 0, 9, 6, '每出一张牌获得一金钱，金钱进入展示区作为金钱印记。\n\n别人出牌阶段结束时，你可以花一个金钱印记买走其中一张，也可以放弃。买到的牌加入手牌；桌上仍显示对方原来的完整出牌，并播报你买了哪张。已被收走的牌不能买。')
skill('gift', '恩赐', 1, 7, 3, '出牌阶段前，可选择是否发动技能。\n\n发动技能后，先抽一张牌进入手牌，然后选一张手牌送给另一名玩家。\n\n发动技能后跳过出牌阶段和抽牌阶段。')
skill('stash', '藏拙', 1, 20, 12, '行动结束时，手牌少于五张时，跳过抽牌阶段。\n\n抽牌阶段后，你可以把剩下的任意几张手牌不公示的存入展示区，之后随时将展示区的牌取回。展示区不受急牌影响。\n\n出完手牌不算走完，需要出完展示区的牌才算走完。')
skill('scavenge', '顺手牵羊·新世代', 1, 8, 1, '出牌阶段前，可选择是否发动技能。\n\n发动技能后，选择一名玩家，随机抽取他的手牌加入到自己的手牌中，抽取数量不超过四张，如果抽取数量超过一张，则跳过出牌阶段，如果抽完则视为该名玩家走完。\n\n发动技能后跳过抽牌阶段。')
skill('pressure', '施压', 1, 14, 12, '随时可以消耗一张实际点数为 2 的牌，弃置进弃牌堆，指定另一名玩家抓四张或者禁用技能三回合。')
skill('suitmark', '烙印', 1, 9, 9, '管住别人时，给被管者一个花色印记，如：黑桃烙印印记，展示在展示区。单一花色自动使用；多种花色从本手中选，没有花色时可任选。勾、点、叉、压和死压也同样适用。\n\n对方攒到两个印记后，立即：\n♠♠：抓两张。\n♥♥：弃掉两张最大的牌。\n♣♣：抽取两张，然后最多留一张。\n♦♦：无效果。\n♠♥：抓两张，再弃掉一张最大的牌。\n♠♣：抓一张，再抽一张，自选是否留下。\n♥♣：弃掉一张最大的牌，再抽一张，自选是否留下。\n♠♦：抓四张。\n♥♦：弃掉三张最大的牌。\n♣♦：抽取三张，然后最多留一张。\n然后弃置所有花色烙印印记。\n\n获得自由牌权时，拥有印记的玩家，每个印记：\n♠：禁用技能两回合。\n♥：禁用技能一回合，牌点数降低一级（最低不小于数值3）一回合。\n♣：牌点数降低一级（最低不小于数值3）两回合。\n♦：禁手一回合。\n保留花色印记。\n\n没留下的牌进入弃牌堆。')
skill('double', '拆解', 1, 7, 5, '每次出牌，你可以把一张 K、A、2 或主牌当成两张或三张 3、4、5 来用，但不能变成本局主牌。拆解后的点数和花色由你分别指定。\n\n选好原牌后点“拆解”，指定结果，再和其他牌一起出。每次只能“拆解”一张原牌；出牌数量按指定的两张或三张算，实际只消耗这一张。')
skill('seven', '重铸·七音', 2, 8, 8, '轮到你时，可以把 3、4、5、6 存成印记，最多七枚，作为七音印记记入展示区。\n\n攒满七枚后，点“使用重铸·七音”，任意指定七张牌的点数和花色，消耗全部七音印记后将这七张加入手牌。可以留到之后再出，实际出牌仍须符合牌型规则。存成印记的牌不再需要出完。')
skill('formless', '重铸·万化', 2, 8, 6, '你可以忽略花色来“回”，而且一轮内不限次数。牌型和张数仍须与对方相同。\n\n手牌少于三张时不能回。王、2 和主牌仍不能作为回牌或被回牌的主体。')
skill('blood', '重铸·嗜血', 2, 10, 5, '你跳过抽牌阶段。\n\n开局时弃掉的五张牌，每一张作为一枚嗜血印记，记在你的展示区。\n\n每出一次牌减一嗜血印记。出牌阶段未出牌时，加一嗜血印记。嗜血印记最低为零。\n\n抽牌阶段结束时，弃牌或抽牌，使你的手牌数等于嗜血印记数量。')
skill('ascend', '重铸·至高强化', 2, 8, 8, '你的 3 至 A 初始不提高，2、主牌和王不变。加点时不会跳过主牌原来的位置，最高到主牌，手牌会标出变化。\n\n出牌阶段，发动技能将印面为 2 的牌放入展示区，作为一枚至高强化印记。每枚至高强化印记可以使你本局加点幅度再加一级。')
skill('extra', '重铸·丰收', 2, 6, 2, '抽牌阶段，你只可以选择抓二或三张。\n\n急牌和其他技能规定的抓牌数量不变。')
skill('redirect', '替身', 3, 6, 1, '抽牌阶段，你可以让另一名玩家替你抓一张，自己不抓；也可以照常自己抓。')
skill('request', '窃取', 3, 9, 3, '抽牌阶段，你可以不从牌堆抓牌，改为向其他每个在场玩家各要两张，由对方选牌。\n\n不足两张就全部交出；有人因此出空手牌，视为出完。')
skill('gather', '取舍', 3, 12, 6, '你拿到的A（除了黑桃A）、2、主牌和大小王会被弃掉，再补其他牌，开局发牌也一样，开局选牌不会出现2、主牌和大小王。\n\n抽牌阶段，可以选择抓一至三张。')
skill('wild', '千变', 3, 10, 10, '你的所有 A 都能当赖子，也能按原本的 A 出。选中 A 后点“指定赖子”，逐张选择它代替的点数和花色，再出牌。\n\n可替代王牌，不可替代急牌，普通替代要和其他牌一起出。回牌指定花色，桌上会显示原牌和替代结果。')
skill('twins', '如影随形', 3, 14, 14, '你拥有两组手牌。\n\n开局把手牌分成两组，每组均为七张。你控制两个身份，依次行动，用“手牌 A／B”切换。\n\n两个身份各自出牌、发牌、计算状态，也能分别被技能或急牌选中。任意一个身份走完，视为全部两个手牌走完。总手牌数算作N+1个，N为参与玩家人数。')
skill('pursuit', '追猎', 3, 6, 3, '出牌阶段，如果没有能管上的牌，就一直抓，抓到能管上为止，最多五张。抓满还管不上就不出。\n\n一旦你的手牌可以以任意方式管上，则不再有任意形式的抓牌，他人技能和急牌除外。\n\n停止抓牌时可选择不出。\n\n跳过抽牌阶段。')
skill('debt', '奉还', 3, 9, 6, '每管上别人一次，就给对方一枚奉还印记，记入展示区，可以累积。\n\n当你拿到自由牌权时，其他在场玩家各抓自己印记数那么多张牌，并禁用技能那么多回合，然后清除所有印记。')
skill('judgment', '投骰', 4, 12, 12, '轮到你且没有能管上的牌时，可以翻牌堆顶一张判定。如果判定牌属于黑桃，就视为出了相同牌型、主体大一级的牌；花色和带牌与上一名玩家相同。此判定不可以用于“压”“死压”和“死点”，因为没有比这些牌型还大的牌了。\n\n如果判定失败就抓五张并跳过出牌阶段和抽牌阶段。')
skill('trade', '献祭', 4, 10, 2, '出牌阶段前，可以用一张王换六张牌、主牌换五张、2 换四张。然后进入出牌阶段。\n\n抽牌阶段，还可以选择是否翻一张判定牌：如果判定结果是黑色，则根据牌面数值额外抽与数值相同张数牌，其余花色没有额外效果。')
skill('bond', '灵魂绑定', 4, 9, 3, '开局选择一名玩家的一个手牌进行绑定。\n\n你的回合，可以选择更换另一名玩家的一个手牌进行绑定。\n\n直到更换绑定目标。双方能看到对方手牌和展示区不公开的内容。\n\n绑定期间，双方抽牌阶段可选一至两张，而不是一张。\n\n在绑定期间，抽牌阶段、他人技能和急牌导致的弃牌和发牌，绑定的双方均要享受发牌，如玩家1和玩家2绑定，玩家3给玩家2发动急牌抽2张，那么玩家1也要抽两张。\n\n你禁用技能时，所有效果消失，绑定对方禁用技能时，对你无任何影响。绑定双方禁手不会影响另一人。')
skill('duel', '死斗', 4, 8, 6, '获得自由牌权时，可以发起拼点。所有在场玩家各暗选一张牌，选齐后同时公开并弃掉，作为判定牌。\n\n除你之外，判定牌不大于你的玩家，还要弃掉最大的三张手牌，并禁用技能两回合，不足三张就保留最小的一张。弃牌之后，手牌数不足五张的抽牌补齐至五张。按技能之后的点数比较。')
skill('formation', '节流', 4, 9, 9, '出 4A4A4 牌型时，可省略一张4和一张A，即4A4为基础4A4A4，更大的为444A，以此类推。\n\n三张同点就能当炸弹，而不是四张。三张的炸弹小于最小的四张的炸弹。')
skill('redemption', '救赎之力', 5, 8, 6, '拿到自由牌权时，清除场上所有位于展示区的手牌，包括所有印记，嗜血印记会保留一枚。\n\n一次清除中，每清除一种印记，自选弃置一张牌。')
skill('chase_force', '追击之力', 5, 14, 14, '你的牌数值降低一级。\n\n每有一名玩家出完牌，你的牌数值增加两级。特别地，有多组手牌的玩家如果出完牌，你的牌数值增加四级。\n\n每有一名玩家有多组手牌，你的牌数值增加五级。\n\n普通牌最高升到主牌；王牌和急牌不参与加点。')
skill('equilibrium', '平衡之力', 5, 12, 12, '所有手牌数量比你多的玩家，所有抽牌方式（包括技能、急牌赠送、抽牌阶段抽牌等）最多一次抽取一张。\n\n手牌数量比你多九张的玩家，禁用技能直到手牌不比你多九张，无法通过跨牌型出牌，例如KKKKK管56789（牌型不同），4A4A4管炸弹，55555管2222，66666管双王炸等，每多一张手牌，所有手牌数值减一级。')
skill('shadow', '阴影之力', 5, 8, 8, '获得自由牌权后，禁用下一位玩家和被管住玩家的技能一回合，并使其明牌一回合。\n\n场上玩家，通过任意方式被禁用技能的玩家禁止出牌一回合，无论禁用技能几回合，被禁用技能一次禁手一回合，并随机弃置一张牌。')
skill('imprison', '禁锢之力', 5, 8, 8, '除你之外，每在非抽牌阶段获得一张牌，则该名玩家获得一枚禁锢印记，记在展示区。\n\n一旦一名玩家获得多于等于两枚禁锢印记，清除所有禁锢印记，多于一枚禁锢印记的每枚禁锢印记使该名玩家立即禁用技能两回合。')
skill('encourage', '激励之力', 5, 12, 10, '不在你的抽牌阶段，每获得一张手牌，获得一枚激励印记，记在展示区。\n\n获得自由牌权时，可以选择消耗激励印记，每消耗一枚激励印记可以自选弃置一张牌。')

GROUPS = {0: '标准', 1: '突破', 2: '重生', 3: '多多益善', 4: '智谋', 5: '终极力量'}

def available(options):
    groups = {0} | set(options.get('skillDlc', []))
    disabled = set(options.get('disabledSkills', []))
    return [s for s in SKILLS.values() if s['group'] in groups and s['id'] not in disabled]
